<template><view v-if="props.operations.current()&&props.operations.pending.value.length" class="cw-recovery" data-writeoff-recovery="pending"><text class="cw-subtitle">原核销操作待核对</text><text>请求中断时先查询原编号。恢复只使用原编号及完整原内容，不新建第二次核销。</text><view v-for="intent in props.operations.pending.value" :key="intent.request_key" class="cw-recovery-row"><text class="cw-request-key">{{ intent.request_key }}</text><text>{{ customerWriteoffResultMessage(props.operations.states.value[intent.request_key]?.result??null) }}</text><text v-if="props.operations.states.value[intent.request_key]?.error" class="cw-error">{{ props.operations.states.value[intent.request_key]?.error }}</text><view class="cw-controls"><button :disabled="props.operations.busy.value" @tap="props.operations.check(intent)">查询原结果</button><button v-if="props.operations.canRestore(intent)" :disabled="props.operations.busy.value" @tap="props.operations.restore(intent)">显式恢复原核销</button><button v-if="props.operations.canAbandon(intent)" :disabled="props.operations.busy.value" @tap="props.operations.abandon(intent)">放弃尚未执行的意图</button><button v-if="customerWriteoffTerminal(props.operations.states.value[intent.request_key]?.result??null)" :disabled="props.operations.busy.value" @tap="props.operations.acknowledge(intent)">已核对，关闭记录</button><button v-if="props.operations.readable()" :disabled="props.operations.busy.value" @tap="props.operations.manager.go('writeoff',{orderId:intent.body.order_id,orderNo:intent.order_no})">重新读取原订单</button></view></view></view></template>
<script setup lang="ts">
import {customerWriteoffResultMessage,customerWriteoffTerminal} from '@/utils/customerWorkWriteoff';
import type {CustomerWorkWriteoffOperations} from '@/composables/useCustomerWorkWriteoffOperations';
const props=defineProps<{operations:CustomerWorkWriteoffOperations}>();
</script>
